"""Build the new-unit content layer without regenerating established chapters 4–6."""
from pathlib import Path
import json

root = Path(__file__).resolve().parents[1]
data = json.loads((root / 'content/winemaking.json').read_text())
(root / 'dist/winemaking-data.js').write_text(
    '/* Generated by scripts/build-winemaking.py; edit content/winemaking.json. */\n'
    + 'const winemakingData=' + json.dumps(data, ensure_ascii=False, indent=1) + ';\n')
print(f"Built {len(data['chapters'])} chapters / {len(data['units'])} framework units.")
